def std(self, ddof: int=1, engine: Literal['cython', 'numba'] | None=None, engine_kwargs: dict[str, bool] | None=None, numeric_only: bool=False, skipna: bool=True):
    if maybe_use_numba(engine):
        from pandas.core._numba.kernels import grouped_var
        return np.sqrt(self._numba_agg_general(grouped_var, executor.float_dtype_mapping, engine_kwargs, min_periods=0, ddof=ddof, skipna=skipna))
    else:
        return self._cython_agg_general('std', alt=lambda x: Series(x, copy=False).std(ddof=ddof, skipna=skipna), numeric_only=numeric_only, ddof=ddof, skipna=skipna)

def decode(self, encoding, field: str='strict', dtype: str | DtypeObj | None=None):
    if dtype is not None and (not is_string_dtype(dtype)):
        raise ValueError(f'dtype must be string or object, got dtype={dtype!r}')
    if dtype is None and using_string_dtype():
        dtype = 'str'
    if encoding in _cpython_optimized_decoders:
        f = lambda x: x.decode(encoding, field)
    else:
        decoder = codecs.getdecoder(encoding)
        f = lambda x: decoder(x, field)[0]
    arr = self._data.array
    result = arr._str_map(f)
    return self._wrap_result(result, dtype=dtype)

def _serialize(self):
    res = dict()
    if self._self_request:
        res['$self_request'] = self._self_request._serialize()
    for name, route_mapping in self._route_mappings.items():
        res[name] = dict()
        res[name]['mapping'] = route_mapping.mapping._serialize()
        res[name]['router'] = route_mapping.router._serialize()
    return res

def hermroots(c):
    [c] = pu.as_series([c])
    if len(c) <= 1:
        return np.array([], dtype=c.dtype)
    if len(c) == 2:
        return np.array([-0.5 * c[0] / c[1]])
    m = hermcompanion(c)[::-1, ::-1]
    r = np.linalg.eigvals(m)
    r.sort()
    from numpy.linalg._linalg import _to_real_if_imag_zero
    r = _to_real_if_imag_zero(r, m)
    return r
